"use client";

import { useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useAuthStore, UserPwa } from "../../../../../store/auth.store"; // Ajusta ruta
import { Center, Loader, Text } from "@mantine/core";
import { fetchPwaUserProfile } from "../../../../../lib/services/auth.frontend.service"; // Ajusta ruta

function GoogleCallbackContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { setUser, setLoading, setError, token: currentToken } = useAuthStore();

  useEffect(() => {
    // Solo ejecutar si no tenemos ya un token en el store (evita doble ejecución si el componente se re-monta)
    if (currentToken) {
      console.log(
        "GoogleCallback: Token already in store, navigating based on user data."
      );
      const user = useAuthStore.getState().user;
      if (!user?.countryOfOrigin) {
        router.replace("/set-country");
      } else {
        router.replace("/dashboard");
      }
      return;
    }

    const token = searchParams.get("token");
    const errorParam = searchParams.get("error");

    if (errorParam) {
      const decodedError = decodeURIComponent(errorParam);
      console.error(
        "GoogleCallback: Error from backend redirect:",
        decodedError
      );
      setError(decodedError);
      router.replace(`/login?error=${encodeURIComponent(decodedError)}`); // Redirigir a login con el error
      return;
    }

    if (token) {
      console.log("GoogleCallback: Token received:", token);
      setLoading(true);
      fetchPwaUserProfile(token)
        .then((userData) => {
          if (userData && userData.id) {
            // Verificar que userData sea válido
            console.log("GoogleCallback: User profile fetched:", userData);
            setUser(userData, token); // Guarda token y usuario en el store
            if (!userData.countryOfOrigin) {
              router.replace("/set-country");
            } else {
              router.replace("/dashboard");
            }
          } else {
            throw new Error("User data not found after login.");
          }
        })
        .catch((err) => {
          console.error(
            "GoogleCallback: Failed to fetch profile or process token:",
            err
          );
          setError(err.message || "Error al obtener información del usuario.");
          // Limpiar token si falló la obtención del perfil
          useAuthStore.getState().logout(); // Llama a logout para limpiar el token del store si se guardó
          localStorage.removeItem("pwa-auth-storage"); // Limpia también el localStorage si es necesario
          router.replace(
            `/login?error=${encodeURIComponent(
              err.message || "Error al obtener información del usuario."
            )}`
          );
        })
        .finally(() => {
          // setLoading(false); // setUser ya pone isLoading a false
        });
    } else {
      console.error(
        "GoogleCallback: No token or error found in query params. Redirecting to login."
      );
      setError("Fallo en la autenticación. No se recibió token.");
      router.replace("/login");
    }
  }, [searchParams, router, setUser, setLoading, setError, currentToken]); // Añade currentToken

  return (
    <Center style={{ height: "100vh", flexDirection: "column" }}>
      <Loader />
      <Text mt="md">Verificando autenticación con Google...</Text>
    </Center>
  );
}

export default function GoogleCallbackPage() {
  return (
    <Suspense
      fallback={
        <Center style={{ height: "100vh" }}>
          <Loader />
        </Center>
      }
    >
      <GoogleCallbackContent />
    </Suspense>
  );
}
